def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        use_counts = {}
        freqs = {}
        hit_count = 0
        miss_count = 0

        def get_freq(key):
            if key in use_counts:
                return use_counts[key]

            if len(freqs) < maxsize:
                freqs[key] = len(freqs)
            else:
                min_key = min(freqs.items(), key=lambda x: x[1])[0]
                freqs[key] = freqs[min_key]
                del freqs[min_key]

            return freqs[key]

        def wrapped(*args, **kwargs):
            nonlocal hit_count
            nonlocal miss_count
            key = (func, args, tuple(kwargs.items()) if typed else None)
            if key in cache:
                hit_count += 1
                use_counts[key] += 1
                return cache[key]
            else:
                miss_count += 1
                if len(cache) < maxsize:
                    result = func(*args, **kwargs)
                    cache[key] = result
                    get_freq(key)
                    use_counts[key] = 1
                    return result
                else:
