def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    try:
        # Check that the candidate has all the methods of the interface
        for method in iface.__dict__.values():
            if not callable(getattr(candidate, method.__name__)):
                raise NotImplementedError(
                    "Method {0} is not implemented by {1}".format(
                        method.__name__, candidate
                    )
                )

        # Check that the methods of the candidate have the correct signature
        for method in candidate.__dict__.values():
            if method.__name__ in iface.__dict__:
                expected = iface.__dict__[method.__name__]
                actual = candidate.__dict__[method.__name__]
                if not expected.__code__.co_argcount == actual.__code__.co_argcount:
                    raise TypeError(
                        "Method {0} in {1} has incorrect argument signature".format(
                            method.__name__, candidate
                        )
                    )

        # If the candidate is tentative, check that it is virtual
        if tentative:
            if not as_interface(candidate) == iface:
                raise ValueError(
                    "Tentative class {0} does not correctly provide {1}".format(
                        candidate, iface
                    )
                )
    except AttributeError:
        raise ValueError(
            "Candidate {0} is not a valid class for {1} interface".format(
                candidate, iface
            )
        )

    return True

