def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    spec_defaults = {}
    args = [i for i in self.args if isinstance(i, Argument)]
    for arg in args:
        if not isinstance(arg.default, NoDefault):
            spec_defaults[arg.name] = arg.default
            if isinstance(arg, DictOption):
                if arg.scheme:
                    if arg.scheme.get_spec_defaults():
                        spec_defaults[arg.name] = arg.scheme.get_spec_defaults()
    return spec_defaults

