def get_option_spec(command_name, argument_name):
    """Returns the OptionSpec for the specified option name."""
    spec = self.option_specs.get(command_name)
    if spec is None:
        return None
    for arg in spec.args:
        if arg.name == argument_name:
            return arg
    return None

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silenced_args = []
    for arg in args:
        if arg.startswith('--'):
            silenced_args.append(arg)
    return silenced_args

