def validate_min_max_args(self, args):
    if not (isinstance(args, dict) and 'min_' in args and 'max_' in args):
        raise TypeError('Expected a dictionary with \'min_\' and \'max_\' keys')
    min_ = args['min_']
    max_ = args['max_']
    if not (isinstance(min_, int) and isinstance(max_, int)):
        raise TypeError('Expected int values for \'min_\' and \'max_\'')
    if not (min_ <= max_):
        raise ValueError('Expected \'min_\' to be less than or equal to \'max_\'')
    return args

def get_nested_custom_and_control_args(self, args):
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.endswith("_control"):
            control_args[arg] = args[arg]
        elif arg.endswith("_custom"):
            custom_args[arg] = args[arg]
        else:
            nested_args[arg] = args[arg]

    return (control_args, nested_args, custom_args)

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra_vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars

    """
    if not vars_dict or not extra_vars:
        return vars_dict
    for extra_var in extra_vars:
        vars_dict[extra_var] = extra_var
    return vars_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    # get the plugin spec file
    spec_file = os.path.join(plugin_dir, 'plugin_spec.json')
    with open(spec_file, 'r') as f:
        spec = json.load(f)

    # create a flat dict
    attributes = {}
    for key, value in spec.items():
        attributes[key] = value

    return attributes

def strip_root(path, root):
    if not path.startswith(root):
        raise ValueError("Path {0} is not beneath root {1}.".format(path, root))

    return path[len(root):]
